type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();
    
    let mut ret: Matrix<i8> = Vec::new();
    
    if len == r {
        // Treat array as column vector: broadcast each element across its row
        // Matrix[i][j] = a[i] for all valid i, j
        let mut i = 0;
        while i < r {
            let mut row: Vec<i8> = Vec::new();
            let mut j = 0;
            while j < c {
                row.push(a[i]);
                j += 1;
            }
            ret.push(row);
            i += 1;
        }
    } else {
        // len == c: Treat array as row vector: replicate entire array for each row
        // Matrix[i][j] = a[j] for all valid i, j
        let mut i = 0;
        while i < r {
            let mut row: Vec<i8> = Vec::new();
            let mut j = 0;
            while j < c {
                row.push(a[j]);
                j += 1;
            }
            ret.push(row);
            i += 1;
        }
    }
    
    ret
}